mapper.sql:
FROM doctor_schedule s
INNER JOIN doctor d ON d.id = s.doctor_id
INNER JOIN department dep ON dep.id = s.department_id
WHERE s.deleted = 0

    AND s.status = 'PUBLISHED'
    AND d.deleted = 0 AND d.status = 1
    AND dep.deleted = 0 AND dep.status = 1
    AND s.start_time > DATE_ADD(#{now}, INTERVAL s.cancel_before_minutes MINUTE)

AND s.doctor_id = #{doctorScope}
AND s.doctor_id = #{filter.doctorId}
AND s.department_id = #{filter.departmentId}
AND s.status = #{filter.status}
AND s.start_time >= #{fromUtc}
AND s.start_time < #{toUtc}

mapper.select:
SELECT 

ORDER BY s.start_time ASC, s.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM doctor_schedule
WHERE doctor_id = #{doctorId} AND deleted = 0
  AND start_time < #{end} AND end_time > #{start}
  AND id != #{excludeId}

mapper.update:
UPDATE doctor_schedule SET status = #{status}, version = version + 1,
    updated_at = #{now}
WHERE id = #{id} AND deleted = 0

UPDATE doctor_schedule SET status = 'CANCELLED', deleted = 1,
    version = version + 1, updated_at = #{now}
WHERE id = #{id} AND deleted = 0
